    // 编辑规格属性在回车或者失焦时调用立即生成
    handleEnter(newText, oldText) {
      // 生成规格
      this.attrs[this.editTagIndex[0]].detail[this.editTagIndex[1]] = newText;
      // 清空编辑状态
      this.editTagIndex = [];
      // 生成规格组合
      this.generate(1, (newText, oldText) => {
        // 遍历所有规格组合
        this.manyFormValidate.forEach((item, index) => {
          Object.keys(item).forEach((key) => {
            if (typeof item[key] === "string" && item[key].includes(oldText)) {
              // 替换
              item[key] = item[key].replace(oldText, newText);
            }
            if (key === "detail" && typeof item[key] === "object") {
              Object.keys(item[key]).forEach((key2) => {
                if (typeof item[key][key2] === "string" && item[key][key2].includes(oldText)) {
                  // 替换
                  item[key][key2] = item[key][key2].replace(oldText, newText);
                }
              })
            }
          });
        });
      }, newText, oldText);
    },
    delImage() {
      this.oneFormBatch[0].pic = "";
    }
  },
};
